    records = records.copy()
    if records.empty:
        records["BOSALTIM_TARIHI_DT"] = pd.Series(dtype="datetime64[ns]")
        return records

    records["BOSALTIM_TARIHI_DT"] = pd.to_datetime(records["BOSALTIM_TARIHI"], format="%d.%m.%Y", errors="coerce")
    return records


