def movements_with_parsed_date(movements):
    """Hareket kayıtlarına, tarih bazlı filtreleme için ayrıştırılmış bir tarih sütunu ekler."""

    movements = movements.copy()
    if movements.empty:
        movements["TARIH_DT"] = pd.Series(dtype="datetime64[ns]")
        return movements

    movements["TARIH_DT"] = pd.to_datetime(movements["TARIH"], format="%d.%m.%Y %H:%M", errors="coerce")
    return movements


def enrich_movements_with_container_info(movements, df):
    """Hareket kayıtlarına, ana veritabanından hat/gemi/saha bilgilerini ekler (rapor için)."""

    if movements.empty:
        return movements

    info_cols = [c for c in ["_SEARCH", "AGENT", "VESSEL NAME", "AREA", "SIZE", "TYPE"] if c in df.columns]
    info = df[info_cols].rename(columns={"_SEARCH": "KONTEYNER"})
    info["AGENT"] = info["AGENT"].apply(normalize_line) if "AGENT" in info.columns else "-"

    merged = movements.merge(info, on="KONTEYNER", how="left")
    return merged


def build_excel_bytes(export_df, sheet_name="Rapor"):
    """Bir DataFrame'i indirilebilir bir Excel dosyasının bayt içeriğine çevirir."""

    buffer = io.BytesIO()
    with pd.ExcelWriter(buffer, engine="openpyxl") as writer:
        export_df.to_excel(writer, index=False, sheet_name=sheet_name[:31])
    return buffer.getvalue()


def build_cfs_excel_bytes(cfs_df):
    """CFS kayıtlarını, ALPORT'un orijinal dosya formatına uygun şekilde
    'TRANSIT' ve 'ARAÇLI' olmak üzere iki ayrı sekimde Excel'e çevirir."""

    transit_cols = {
        "KONTEYNER": "KONTEYNER NO", "BOYUT": "SIZE", "GEMI_ADI": "GEMİ ADI",
        "VOYAGE_NUMBER": "VOYAGE NUMBER", "REMARK": "REMARK", "AGENT": "AGENT",
        "BOSALTIM_TARIHI": "STRIPPED DATE", "DESTINATION": "DESTINATION",
        "BOS_KONTEYNER_TARIHI": "EMPTY DATES", "CIKIS_TARIHI": "EXIT DATE",
        "TERMINAL": "STRIPPED TERMINAL",
    }
    vehicle_cols = {
        "KONTEYNER": "KONTEYNER NO", "BOYUT": "SIZE", "GEMI_ADI": "GEMİ ADI",
        "VOYAGE_NUMBER": "VOYAGE NUMBER", "REMARK": "REMARK", "AGENT": "AGENT",
        "BOSALTIM_TARIHI": "STRIPPED DATE", "ARAC_SAYISI": "NUMBER OF VEHICLE",
        "BOS_KONTEYNER_TARIHI": "EMPTY DATES", "CIKIS_TARIHI": "GATE OUT",
        "MODEL": "MODEL", "SASI_NUMARASI": "CHASSI NUMBER",
        "TERMINAL": "STRIPPED TERMINAL", "YUKLEME_GEMISI": "LOADING VESSEL",
        "YUKLEME_VOYAGE_NO": "VOYAGE NO", "EC_YUKLEME_TARIHI": "E/C LOADED DATE/TIME",
    }

    transit_df = cfs_df[cfs_df["KARGO_TIPI"] == "TRANSIT"]
    vehicle_df = cfs_df[cfs_df["KARGO_TIPI"] == "ARAÇ"]

    buffer = io.BytesIO()
    with pd.ExcelWriter(buffer, engine="openpyxl") as writer:
        if not transit_df.empty:
            transit_out = transit_df[list(transit_cols.keys())].rename(columns=transit_cols)
        else:
            transit_out = pd.DataFrame(columns=list(transit_cols.values()))
        transit_out.to_excel(writer, index=False, sheet_name="DAILY TRANSIT STRIPPED")

        if not vehicle_df.empty:
            vehicle_out = vehicle_df[list(vehicle_cols.keys())].rename(columns=vehicle_cols)
        else:
            vehicle_out = pd.DataFrame(columns=list(vehicle_cols.values()))
        vehicle_out.to_excel(writer, index=False, sheet_name="DAILY VEHICLES STRIPPED")

    return buffer.getvalue()


def build_consolidated_report_excel(df, remaining_df, movements, cfs_records, start_date, end_date, dash_stats, line_breakdown, dwell_df):
    """Dashboard'daki tüm ana metrikleri (envanter özeti, hat kırılımı, bekleme
    süresi, dönem içi hareketler) tek bir çok sekmeli Excel raporunda toplar."""

    buffer = io.BytesIO()

    with pd.ExcelWriter(buffer, engine="openpyxl") as writer:

        # --- ÖZET ---
        summary_rows = [
            {"Metrik": "Rapor Aralığı", "Değer": f"{start_date.strftime('%d.%m.%Y')} — {end_date.strftime('%d.%m.%Y')}"},
            {"Metrik": "Oluşturulma Tarihi", "Değer": datetime.now().strftime("%d.%m.%Y %H:%M")},
            {"Metrik": "Toplam Envanter", "Değer": len(df)},
            {"Metrik": "Limanda Kalan", "Değer": len(remaining_df)},
            {"Metrik": "Dolu 20'", "Değer": dash_stats["dolu_20"]},
            {"Metrik": "Boş 20'", "Değer": dash_stats["bos_20"]},
            {"Metrik": "Dolu 40'", "Değer": dash_stats["dolu_40"]},
            {"Metrik": "Boş 40'", "Değer": dash_stats["bos_40"]},
            {"Metrik": "Toplam TEU", "Değer": dash_stats["total_teu"]},
        ]
        pd.DataFrame(summary_rows).to_excel(writer, index=False, sheet_name="Özet")

        # --- HAT BAZLI KIRILIM ---
        if not line_breakdown.empty:
            line_breakdown.to_excel(writer, index=False, sheet_name="Hat Bazlı Kırılım")
        else:
            pd.DataFrame(columns=["Hat"]).to_excel(writer, index=False, sheet_name="Hat Bazlı Kırılım")

        # --- BEKLEME SÜRESİ ---
        if not dwell_df.empty:
            dwell_df.drop(columns=["Kritik"], errors="ignore").to_excel(writer, index=False, sheet_name="Bekleme Süresi")
        else:
            pd.DataFrame(columns=["Konteyner"]).to_excel(writer, index=False, sheet_name="Bekleme Süresi")

        # --- DÖNEM İÇİ HAREKETLER (kapı çıkışı + gemiye yükleme) ---
        if not movements.empty:
            mv_dated = movements_with_parsed_date(movements)
            mv_mask = (mv_dated["TARIH_DT"].dt.date >= start_date) & (mv_dated["TARIH_DT"].dt.date <= end_date)
            mv_period = mv_dated[mv_mask].drop(columns=["TARIH_DT"], errors="ignore")
        else:
            mv_period = movements
        if not mv_period.empty:
            mv_period.to_excel(writer, index=False, sheet_name="Kapı-Gemi Hareketleri")
        else:
            pd.DataFrame(columns=MOVEMENT_COLUMNS).to_excel(writer, index=False, sheet_name="Kapı-Gemi Hareketleri")

        # --- DÖNEM İÇİ CFS KAYITLARI ---
        if not cfs_records.empty:
            cfs_dated = cfs_records_with_parsed_date(cfs_records)
            cfs_mask = (cfs_dated["BOSALTIM_TARIHI_DT"].dt.date >= start_date) & (cfs_dated["BOSALTIM_TARIHI_DT"].dt.date <= end_date)
            cfs_period = cfs_dated[cfs_mask].drop(columns=["BOSALTIM_TARIHI_DT"], errors="ignore")
        else:
            cfs_period = cfs_records
        if not cfs_period.empty:
            cfs_period.to_excel(writer, index=False, sheet_name="CFS Kayıtları")
        else:
            pd.DataFrame(columns=CFS_COLUMNS).to_excel(writer, index=False, sheet_name="CFS Kayıtları")

    return buffer.getvalue()


def classify_size(size_value):
    """SIZE sütunundaki değerden 20 ya da 40 ayak sınıfını tespit eder
    (örn. '20', '20DV', "20'", 'GP20' gibi farklı yazımları destekler)."""

    if not size_value or size_value == "-":
        return None
    match = re.search(r"(20|40|45)", str(size_value))
    return match.group(1) if match else None


def classify_full_empty(status_value):
    """FULL-MTY sütunundaki değerden dolu/boş durumunu tespit eder.
    ALPORT'un gerçek verisinde şu kodlar kullanılıyor: FCL/FCLD (dolu — Full
    Container Load), EMPTY (boş), EXP (export — sahada neredeyse her zaman
    dolu konteynerdir), ayrıca genel FULL/DOLU/BOŞ/MTY yazımları da desteklenir."""

    if not status_value or status_value == "-":
        return None
    v = str(status_value).upper().strip()
    if v in ("E", "EMP") or "MT" in v or "EMP" in v or "BOŞ" in v or "BOS" in v:
        return "EMPTY"
    if v == "F" or "FUL" in v or "DOLU" in v or v in ("FCL", "FCLD", "EXP"):
        return "FULL"
    return None


def compute_teu(size_value):
    """Konteynerin TEU (Twenty-foot Equivalent Unit) katkısını hesaplar."""

    if not size_value or size_value == "-":
        return 1.0
    match = re.search(r"(\d+)", str(size_value))
    if not match:
        return 1.0
    feet = int(match.group(1))
    return round(feet / 20, 2)


def compute_yard_dashboard(remaining_df):
    """Limanda kalan konteynerlerin boyut/durum dağılımını ve toplam TEU'sunu hesaplar."""

    work = remaining_df.copy()

    size_col = work["SIZE"] if "SIZE" in work.columns else pd.Series([""] * len(work))
    status_col = work["FULL-MTY"] if "FULL-MTY" in work.columns else pd.Series([""] * len(work))

    work["_SIZE_CLASS"] = size_col.apply(classify_size)
    work["_STATUS_CLASS"] = status_col.apply(classify_full_empty)
    work["_TEU"] = size_col.apply(compute_teu)

    dolu_20 = int(((work["_SIZE_CLASS"] == "20") & (work["_STATUS_CLASS"] == "FULL")).sum())
    bos_20 = int(((work["_SIZE_CLASS"] == "20") & (work["_STATUS_CLASS"] == "EMPTY")).sum())
    dolu_40 = int(((work["_SIZE_CLASS"].isin(["40", "45"])) & (work["_STATUS_CLASS"] == "FULL")).sum())
    bos_40 = int(((work["_SIZE_CLASS"].isin(["40", "45"])) & (work["_STATUS_CLASS"] == "EMPTY")).sum())
    total_teu = round(work["_TEU"].sum(), 1)
    classified_total = dolu_20 + bos_20 + dolu_40 + bos_40
    other_count = len(work) - classified_total

    return {
        "dolu_20": dolu_20,
        "bos_20": bos_20,
        "dolu_40": dolu_40,
        "bos_40": bos_40,
        "total_teu": total_teu,
        "other_count": other_count,
        "total_count": len(work),
    }


def build_occupancy_gauge_svg(percent, size=108, stroke=12):
    """Doluluk oranını (dolu / (dolu+boş)) gösteren dairesel bir SVG gösterge üretir."""

    radius = (size - stroke) / 2
    circumference = 2 * 3.14159265 * radius
    filled_length = (percent / 100) * circumference
    remaining_length = circumference - filled_length

    return f"""
    <svg viewBox="0 0 {size} {size}" width="{size}" height="{size}">
        <circle cx="{size/2}" cy="{size/2}" r="{radius}" fill="none"
                stroke="#E1E6EB" stroke-width="{stroke}" />
        <circle cx="{size/2}" cy="{size/2}" r="{radius}" fill="none"
                stroke="#0F2A44" stroke-width="{stroke}"
                stroke-dasharray="{filled_length:.2f} {remaining_length:.2f}"
                stroke-linecap="round"
                transform="rotate(-90 {size/2} {size/2})" />
    </svg>
    """


def compute_line_breakdown(remaining_df):
    """Limanda kalan konteynerlerin shipping line (hat) bazında dolu/boş
    20'/40' kırılımını hesaplar — ALPORT'un elle tuttuğu 'CONTAINER STOCK
    STATUS' tablosuna benzer bir özet üretir."""

    if remaining_df.empty:
        return pd.DataFrame()

    work = remaining_df.copy()
    work["_LINE"] = work["AGENT"].apply(normalize_line) if "AGENT" in work.columns else "-"
    size_col = work["SIZE"] if "SIZE" in work.columns else pd.Series([""] * len(work))
    status_col = work["FULL-MTY"] if "FULL-MTY" in work.columns else pd.Series([""] * len(work))
    work["_SIZE_CLASS"] = size_col.apply(classify_size)
    work["_STATUS_CLASS"] = status_col.apply(classify_full_empty)

    rows = []
    for line in sorted(work["_LINE"].unique()):
        if line == "-":
            continue
        line_df = work[work["_LINE"] == line]
        rows.append({
            "Hat": line,
            "Dolu 20'": int(((line_df["_SIZE_CLASS"] == "20") & (line_df["_STATUS_CLASS"] == "FULL")).sum()),
            "Boş 20'": int(((line_df["_SIZE_CLASS"] == "20") & (line_df["_STATUS_CLASS"] == "EMPTY")).sum()),
            "Dolu 40'": int(((line_df["_SIZE_CLASS"].isin(["40", "45"])) & (line_df["_STATUS_CLASS"] == "FULL")).sum()),
            "Boş 40'": int(((line_df["_SIZE_CLASS"].isin(["40", "45"])) & (line_df["_STATUS_CLASS"] == "EMPTY")).sum()),
            "Toplam": len(line_df),
        })

    breakdown = pd.DataFrame(rows)
    if not breakdown.empty:
        totals = {
            "Hat": "TOPLAM",
            "Dolu 20'": breakdown["Dolu 20'"].sum(),
            "Boş 20'": breakdown["Boş 20'"].sum(),
            "Dolu 40'": breakdown["Dolu 40'"].sum(),
            "Boş 40'": breakdown["Boş 40'"].sum(),
            "Toplam": breakdown["Toplam"].sum(),
        }
        breakdown = pd.concat([breakdown, pd.DataFrame([totals])], ignore_index=True)

    return breakdown


def compute_cfs_reconciliation(cfs_records, movements):
    """CFS'de boşaltılan konteynerler arasında, henüz ne kapı çıkışı ne de
    gemiye yükleme kaydı olmayanları (yani 'takılı kalmış' olabilecekleri) bulur."""

    if cfs_records.empty:
        return pd.DataFrame()

    gate_set = set(movements[movements["HAREKET"] == "Kapı Çıkışı"]["KONTEYNER"]) if not movements.empty else set()
    load_set = set(movements[movements["HAREKET"] == "Gemiye Yükleme"]["KONTEYNER"]) if not movements.empty else set()

    work = cfs_records.copy()
    work["_HAS_GATE"] = work["KONTEYNER"].isin(gate_set)
    work["_HAS_LOAD"] = work["KONTEYNER"].isin(load_set)

    pending = work[~work["_HAS_GATE"] & ~work["_HAS_LOAD"]].copy()
    if pending.empty:
        return pd.DataFrame()

    pending["_STRIP_DT"] = pd.to_datetime(pending["BOSALTIM_TARIHI"], format="%d.%m.%Y", errors="coerce")
    today = pd.Timestamp(datetime.now().date())
    pending["_DAYS"] = (today - pending["_STRIP_DT"]).dt.days

    result = pending[["KONTEYNER", "KARGO_TIPI", "BOSALTIM_TARIHI", "_DAYS"]].copy()
    result.columns = ["Konteyner", "Kargo Tipi", "Boşaltım Tarihi", "Gün"]
    result = result.sort_values("Gün", ascending=False)

    return result



def compute_dwell_time(remaining_df, threshold_days=21):
    """Limanda kalan konteynerlerin tahliye tarihinden bugüne kaç gün geçtiğini
    hesaplar. DISCHARGE DATE ayrıştırılamayan kayıtlar sonuca dahil edilmez."""

    if remaining_df.empty or "DISCHARGE DATE" not in remaining_df.columns:
        return pd.DataFrame()

    work = remaining_df.copy()
    work["_DISCHARGE_DT"] = pd.to_datetime(work["DISCHARGE DATE"], errors="coerce")
    work = work.dropna(subset=["_DISCHARGE_DT"])

    if work.empty:
        return pd.DataFrame()

    today = pd.Timestamp(datetime.now().date())
    work["_DWELL_DAYS"] = (today - work["_DISCHARGE_DT"]).dt.days
    work["_LINE"] = work["AGENT"].apply(normalize_line) if "AGENT" in work.columns else "-"

    result = work[["CONTAINER", "_LINE", "SIZE", "AREA", "_DWELL_DAYS"]].copy()
    result.columns = ["Konteyner", "Hat", "Boyut", "Saha", "Gün"]
    result["Kritik"] = result["Gün"] >= threshold_days
    result = result.sort_values("Gün", ascending=False)

    return result


def get_container_timeline(container_number):
    """Bir konteynerin kapı çıkışı / gemiye yükleme ve CFS boşaltım kayıtlarını
    tarih sırasıyla birleştirip döndürür. Ana veritabanındaki tahliye tarihi
    de dahil edilir, böylece konteynerin tüm hayat hikâyesi tek listede görünür."""

    events = []

    movements = load_movements()
    if not movements.empty:
        matching = movements[movements["KONTEYNER"] == container_number]
        for _, row in matching.iterrows():
            events.append({
                "date": row["TARIH"],
                "type": movement_label(row["HAREKET"]),
                "detail": row.get("NOT", ""),
                "icon": "🚪" if row["HAREKET"] == "Kapı Çıkışı" else "🚢",
            })

    cfs_records = load_cfs_records()
    if not cfs_records.empty:
        matching_cfs = cfs_records[cfs_records["KONTEYNER"] == container_number]
        for _, row in matching_cfs.iterrows():
            cargo_label = t("cfs_cargo_type_vehicle") if row["KARGO_TIPI"] == "ARAÇ" else t("cfs_cargo_type_transit")
            events.append({
                "date": row["BOSALTIM_TARIHI"],
                "type": f"{t('tab_cfs')} — {cargo_label}",
                "detail": row.get("TERMINAL", ""),
                "icon": "📥",
            })

    def _sort_key(event):
        parsed = pd.to_datetime(event["date"], format="%d.%m.%Y %H:%M", errors="coerce")
        if pd.isna(parsed):
            parsed = pd.to_datetime(event["date"], format="%d.%m.%Y", errors="coerce")
        return parsed if not pd.isna(parsed) else pd.Timestamp.min

    events.sort(key=_sort_key)
    return events


def compute_vessel_summary(df, movements, cfs_records, vessel_name, voyage_number):
    """Belirli bir gemi/voyage ile gelen konteynerlerin şu anki durumunu özetler:
    kaçı sahada, kaçı kapıdan çıktı, kaçı gemiye yüklendi, kaçı CFS'de boşaltıldı."""

    subset = df[(df["VESSEL NAME"] == vessel_name) & (df["VOYAGE NUMBER"] == voyage_number)]
    container_set = set(subset["_SEARCH"])

    gate_set = set(movements[movements["HAREKET"] == "Kapı Çıkışı"]["KONTEYNER"]) if not movements.empty else set()
    load_set = set(movements[movements["HAREKET"] == "Gemiye Yükleme"]["KONTEYNER"]) if not movements.empty else set()
    cfs_set = set(cfs_records["KONTEYNER"]) if not cfs_records.empty else set()
    moved_out = gate_set | load_set

    return {
        "total": len(container_set),
        "remaining": len(container_set - moved_out),
        "gate_out": len(container_set & gate_set),
        "loaded": len(container_set & load_set),
        "cfs": len(container_set & cfs_set),
        "remaining_containers": subset[~subset["_SEARCH"].isin(moved_out)],
    }


def compute_daily_trend(movements, days=14):
    """Son N gün için günlük kapı çıkışı / gemiye yükleme adetlerini
    grafikte kullanılabilecek bir DataFrame olarak döndürür."""

    end_date = datetime.now().date()
    date_index = pd.date_range(end=end_date, periods=days).date

    gate_label = t("movement_gate")
    load_label = t("movement_load")

    if movements.empty:
        return pd.DataFrame({gate_label: [0] * days, load_label: [0] * days}, index=date_index)

    dated = movements_with_parsed_date(movements)
    dated = dated.dropna(subset=["TARIH_DT"])
    dated["DATE_ONLY"] = dated["TARIH_DT"].dt.date

    gate_counts = dated[dated["HAREKET"] == "Kapı Çıkışı"].groupby("DATE_ONLY").size()
    load_counts = dated[dated["HAREKET"] == "Gemiye Yükleme"].groupby("DATE_ONLY").size()

    trend = pd.DataFrame({
        gate_label: [int(gate_counts.get(d, 0)) for d in date_index],
        load_label: [int(load_counts.get(d, 0)) for d in date_index],
    }, index=date_index)

    return trend


def build_shift_summary_text(gate_today, load_today, cfs_today, date_label):
    """Kapı çıkışı, gemiye yükleme ve CFS boşaltımını tek bir paylaşılabilir
    metin özetinde birleştirir (WhatsApp/e-posta ile paylaşıma uygun)."""

    lines = [f"⚓ ALPORT BANJUL — {t('shift_summary_report_title')} ({date_label})", ""]

    lines.append(f"🚪 {t('movement_gate')}: {len(gate_today)}")
    if not gate_today.empty:
        for _, row in gate_today.iterrows():
            lines.append(f"   • {row['KONTEYNER']}")

    lines.append("")
    lines.append(f"🚢 {t('movement_load')}: {len(load_today)}")
    if not load_today.empty:
        for _, row in load_today.iterrows():
            lines.append(f"   • {row['KONTEYNER']}")

    lines.append("")
    lines.append(f"📥 {t('tab_cfs')}: {len(cfs_today)}")
    if not cfs_today.empty:
        for _, row in cfs_today.iterrows():
            lines.append(f"   • {row['KONTEYNER']}")

    total = len(gate_today) + len(load_today) + len(cfs_today)
    lines.append("")
    lines.append(f"{t('shift_summary_total')}: {total}")

    return "\n".join(lines)


def lookup_container(df, raw_number):
    """Tek bir konteyner numarasını veritabanında arar.
    Dönüş: (status, record_or_none, normalized) -- status: 'ok' | 'not_found' | 'duplicate' | 'invalid'"""

    normalized = normalize_container(raw_number)

    if not normalized:
        return "invalid", None, normalized

    if not is_valid_format(normalized):
        return "invalid", None, normalized

    result = df[df["_SEARCH"] == normalized]

    if result.empty:
        return "not_found", None, normalized

    if len(result) > 1:
        return "duplicate", result, normalized

    return "ok", result.iloc[0], normalized


def load_search_history_from_disk(limit=MAX_HISTORY):
    """Diskteki arama geçmişi dosyasından son aramaları okur (oturumlar arası kalıcı)."""

    if not os.path.exists(SEARCH_HISTORY_FILE):
        return []
    try:
        hist_df = pd.read_csv(SEARCH_HISTORY_FILE, dtype=str)
        hist_df = hist_df.tail(limit)
        entries = [{"number": row["KONTEYNER"], "status": row["STATUS"]} for _, row in hist_df.iterrows()]
        return entries[::-1]
    except Exception:
        return []


def append_search_history_to_disk(number, status):
    """Yeni bir aramayı diskteki arama geçmişi dosyasına ekler."""

    row = pd.DataFrame([{
        "KONTEYNER": number,
        "STATUS": status,
        "TARIH": datetime.now().strftime("%d.%m.%Y %H:%M"),
    }])
    try:
        if os.path.exists(SEARCH_HISTORY_FILE):
            row.to_csv(SEARCH_HISTORY_FILE, mode="a", header=False, index=False)
        else:
            row.to_csv(SEARCH_HISTORY_FILE, mode="w", header=True, index=False)
    except Exception:
        pass


def push_history(number, status):
    entry = {"number": number, "status": status}

    st.session_state.search_history = [
        item for item in st.session_state.search_history
        if item["number"] != number
    ]

    st.session_state.search_history.insert(0, entry)
    st.session_state.search_history = st.session_state.search_history[:MAX_HISTORY]

    append_search_history_to_disk(number, status)


